{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "CC-292, the closest analogue, is a pyrimidine-anilino kinase inhibitor with an ether side chain and showed excellent oral bioavailability in a Phase I human study, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Pazopanib, which shares pyrimidine-aniline and sulfonamide features with the query, had an absolute oral bioavailability of 21.4% in cancer patients, just above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Imatinib, a related oral kinase inhibitor with a similar heteroaromatic amine scaffold, has a mean absolute bioavailability of 98% in patients, supporting high oral bioavailability for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Enasidenib, another heteroaromatic oral drug, showed 57.2% absolute bioavailability in humans, providing additional supportive evidence that this type of ionizable, moderately lipophilic molecule can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Raloxifene has only 2% human oral bioavailability due to extensive phenolic glucuronidation and poor solubility; this is contradictory evidence but weakly transferable because the query lacks the phenolic groups responsible for that low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Bazedoxifene has ~6.2% absolute bioavailability in women due to first-pass glucuronidation; despite sharing a basic OCCN ether motif, the query lacks the phenolic SERM scaffold, limiting the transferability of this low-F result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%) based on multiple transferable human absolute-bioavailability data for kinase-inhibitor-like analogues (CC-292 excellent, imatinib 98%, enasidenib 57%, pazopanib 21.4%), which outweigh low-F SERM analogues whose low bioavailability is driven by phenolic glucuronidation absent in the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data exist for the query molecule.",
    "The nearest analogue similarity is only 0.38, so structural transfer is moderate rather than high.",
    "No experimental solubility, permeability, or first-pass metabolism data are available for the query.",
    "The query's sulfonamide and basic pyrrolidine ionization behavior may affect absorption in ways not captured by the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

